#!/usr/bin/env node
/**
 * Sends the same requests to Voxio (chat.voxio.in) and to our replacement
 * (/agents on this backend) and reports any difference in status code,
 * content type, number of stream lines, line shape (keys and value types) or
 * error body. Reply wording is generated by an LLM, so it is not compared.
 *
 *   node scripts/compareWithVoxio.mjs [--ours http://localhost:5001]
 *
 * Needs a published scenario that still has its old Voxio key (vk_...).
 */
import "dotenv/config";
import dns from "dns";
import mongoose from "mongoose";

if (process.env.DNS_SERVERS) dns.setServers(process.env.DNS_SERVERS.split(",").map((s) => s.trim()));
const args = process.argv.slice(2);
const OURS = args.includes("--ours") ? args[args.indexOf("--ours") + 1] : "http://localhost:5001";
const VOXIO = "https://chat.voxio.in";

await mongoose.connect(process.env.MONGODB_URI);
const scenario = await mongoose.connection.db
  .collection("scenarios")
  .findOne({ apiKey: /^vk_/, status: "Published" }, { projection: { apiKey: 1, scenarioName: 1 } });
await mongoose.disconnect();
if (!scenario) throw new Error("No scenario with a Voxio key to compare against.");
const KEY = scenario.apiKey;
console.log(`Scenario: ${scenario.scenarioName}\nVoxio: ${VOXIO}\nOurs:  ${OURS}\n`);

// The structure of a value: keys and types, not contents.
const shape = (v) =>
  v === null ? "null"
    : Array.isArray(v) ? `[${v.length ? shape(v[0]) : ""}]`
    : typeof v === "object" ? `{${Object.keys(v).sort().map((k) => `${k}:${shape(v[k])}`).join(",")}}`
    : typeof v;

const call = async (base, path, body, raw = false) => {
  const r = await fetch(base + path, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: raw ? body : JSON.stringify(body),
  });
  const text = await r.text();
  const type = (r.headers.get("content-type") || "").split(";")[0];
  let lines;
  if (type === "application/x-ndjson") lines = text.trim().split("\n").map((l) => JSON.parse(l));
  return { status: r.status, type, text, lines };
};

let failures = 0;
const compare = (label, v, o, { exactBody = false } = {}) => {
  const problems = [];
  if (v.status !== o.status) problems.push(`status ${v.status} vs ${o.status}`);
  if (v.type !== o.type) problems.push(`content-type ${v.type} vs ${o.type}`);
  if (v.lines && o.lines) {
    if (v.lines.length !== o.lines.length) problems.push(`${v.lines.length} lines vs ${o.lines.length}`);
    v.lines.forEach((line, i) => {
      if (o.lines[i] && shape(line) !== shape(o.lines[i])) {
        problems.push(`line ${i + 1} shape\n      voxio ${shape(line)}\n      ours  ${shape(o.lines[i])}`);
      }
    });
    // Python formatting: ", " / ": " and \u escapes.
    const pyStyle = (t) => t.includes('", "') && !/[^\x00-\x7f]/.test(t);
    if (pyStyle(v.text) !== pyStyle(o.text)) problems.push("JSON formatting differs (Python style)");
  } else if (exactBody && v.text !== o.text) {
    problems.push(`body\n      voxio ${v.text.slice(0, 160)}\n      ours  ${o.text.slice(0, 160)}`);
  }
  console.log(`${problems.length ? "DIFF" : "same"}  ${label}`);
  problems.forEach((p) => console.log(`      ${p}`));
  if (problems.length) failures++;
  return { v, o };
};

const both = async (label, path, body, opts) => {
  const [v, o] = await Promise.all([call(VOXIO, path, body, opts?.raw), call(OURS, path, body, opts?.raw)]);
  return compare(label, v, o, opts);
};

const sid = `cmp${Date.now()}`;
const turn = (text) => ({ session_id: sid, user_input: { user_input: text } });

// Errors and edge cases first: exact bodies.
await both("start_session, empty body {}", "/agents/start_session", {}, { exactBody: true });
await both("start_session, unknown key", "/agents/start_session", { api_key: "vk_doesnotexist" }, { exactBody: true });
await both("process_input, unknown session", "/agents/process_input", { session_id: "nope", user_input: { user_input: "hi" } }, { exactBody: true });
await both("process_input, no user_input", "/agents/process_input", { session_id: sid }, { exactBody: false });

// A whole consultation.
await both("start_session with own session_id", "/agents/start_session", { api_key: KEY, session_id: sid });
const minted = await both("start_session without session_id", "/agents/start_session", { api_key: KEY });
const ids = [minted.v, minted.o].map((r) => r.lines?.[0]?.session_id);
console.log(`      minted ids: voxio ${ids[0]} / ours ${ids[1]} (both should be UUIDs)`);
await both("process_input, bare string (ignored)", "/agents/process_input", { session_id: sid, user_input: "hello" });
const t1 = await both("process_input, first question", "/agents/process_input", turn("Hello, what brings you in today?"));
const end = await both("process_input, end of session", "/agents/process_input", turn("Let's end the session"));
const tutor = await both("process_input, tutor question", "/agents/process_input", turn("Why ask about night pain?"));
await both("start_session again, same id (restart)", "/agents/start_session", { api_key: KEY, session_id: sid });

const said = (r, key) => r.lines?.map((l) => l.out?.[key]).find((x) => x !== undefined);
console.log("\nWhat each said (wording is expected to differ):");
for (const [label, r, key] of [["patient", t1, "speak"], ["goodbye", end, "speak"], ["score", end, "score"], ["tutor", tutor, "response"]]) {
  console.log(`  ${label.padEnd(8)} voxio: ${String(said(r.v, key)).slice(0, 90)}`);
  console.log(`  ${"".padEnd(8)} ours:  ${String(said(r.o, key)).slice(0, 90)}`);
}

console.log(failures ? `\n${failures} difference(s).` : "\nNo differences in status, format or structure.");
process.exit(failures ? 1 : 0);
